def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Continue each matching diagonal pair outward wherever the next cells
    # are still background.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w) or grid[r2][c2] != color:
                    continue
                for sr, sc, start_r, start_c in (
                    (dr, dc, r2, c2),
                    (-dr, -dc, r, c),
                ):
                    nr, nc = start_r + sr, start_c + sc
                    while 0 <= nr < h and 0 <= nc < w and out[nr][nc] == bg:
                        out[nr][nc] = color
                        nr += sr
                        nc += sc
    return out
